from pathlib import Path
import sys,json,gzip,hashlib,csv
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
root=Path.cwd();sys.path.insert(0,str(root/'scripts/reinforcement_learning/rsl_rl'))
from policy_evaluation_evidence import validate_evaluation_bundle
from diagnose_motion_policy_symmetry import rotation_matrix
base=root/'learnings/policy_tuning/RobotLab-Isaac-BeyondMimic-Flat-LW-wheel-v0'
runs={'no_height':('2026-11-05_16-40-14','wheel-to-leg-fixed-start-20261106-001'),'height':('2026-11-06_11-39-51','wheel-to-leg-fixed-start-20261107-001'),'current':('2026-11-07_15-01-47','wheel-to-leg-fixed-start-20261108-001')}
out=base/runs['current'][0]/'evaluations'/runs['current'][1]/'derived';out.mkdir(exist_ok=True)
ref=lambda p:{'path':str(p),'sha256':hashlib.sha256(Path(p).read_bytes()).hexdigest()}
rms=lambda x:float(np.sqrt(np.mean(np.asarray(x)**2)))
def env(v):
 v=[x for x in v if x is not None]
 return {'min':float(min(v)),'max':float(max(v)),'mean':float(np.mean(v))} if v else None
def rpy(q):
 q=np.asarray(q);q=q/np.linalg.norm(q,axis=-1,keepdims=True);w,x,y,z=np.moveaxis(q,-1,0)
 return np.degrees(np.stack([np.arctan2(2*(w*x+y*z),1-2*(x*x+y*y)),np.arcsin(np.clip(2*(w*y-z*x),-1,1)),np.arctan2(2*(w*z+x*y),1-2*(y*y+z*z))],axis=-1))
stats={};data={};inputs=[];rows=[];cycles=[];rt={}
for version,(run,batch) in runs.items():
 stats[version]={}
 for case in ('nominal','randomized'):
  d=base/run/'evaluations'/batch/'raw'/f'fixed-start-{case}-a01'
  validate_evaluation_bundle(d/'result.json');res=json.loads((d/'result.json').read_text())
  with gzip.open(d/'telemetry.json.gz','rt') as f:t=json.load(f)
  assert t['telemetry_status']=='complete' and not t['missing_required_signals']
  assert all(x['complete'] for x in t['signal_status'].values() if x['required'])
  inputs.extend([ref(d/'result.json'),ref(d/'telemetry.json.gz')])
  ss=t['samples'];ps=t['physics_samples'];names=t['joint_names'];md=t['motion_diagnostics'];runtime=md['initial_runtime'];rt[version,case]=runtime
  assert len(ss)==1000 and len(ps)==4000
  arr=lambda k:np.array([s[k] for s in ss]);parr=lambda k:np.array([s[k] for s in ps])
  frame=arr('frame_index');ts=frame/50;ct=ts+.02;ep=arr('episode_id');pt=parr('frame_index')/50+(parr('substep')+1)*.005;pe=parr('episode_id')
  v=parr('joint_velocity');ac=parr('joint_acceleration');tau=parr('applied_torque');computed=parr('computed_torque')
  q=arr('joint_position');qr=arr('reference_joint_position');vr=arr('reference_joint_velocity');z=arr('root_position_w')[:,2];angles=rpy(arr('root_quaternion_w'))
  bp=arr('body_position_w').reshape(-1,len(md['body_names']),3);bref=arr('reference_body_position_w').reshape(bp.shape);zr=bref[:,md['body_names'].index('base_link'),2]
  vz=np.array([(rotation_matrix(s['root_quaternion_w'])@s['root_linear_velocity_b'])[2] for s in ss])
  fz=parr('contact_forces_w').reshape(-1,4,3)[:,:,2];gz=parr('ground_contact_forces_w').reshape(-1,4,3)[:,:,2]
  wx=parr('wheel_center_position_w').reshape(-1,2,3).mean(axis=1)[:,0]
  wheelj=[names.index(n) for n in ['left_wheel_joint','right_wheel_joint']];shankj=[names.index(n) for n in ['left_shank_joint','right_shank_joint']]
  episodes=[];phase=np.full(len(ps),'preparation',dtype=object)
  for e in sorted(set(ep)):
   ci=np.where(ep==e)[0];pi=np.where(pe==e)[0];times=pt[pi]
   off=(np.concatenate([fz[pi],gz[pi]],axis=1)<10).all(axis=1)
   starts=[i for i in range(len(pi)-2) if 1.15<=times[i]<=1.6 and off[i:i+3].all()]
   air=times[starts[0]] if starts else None;land=None
   if starts:
    for k in range(starts[0]+3,len(pi)-2):
     if (fz[pi[k:k+3],:2]>=10).any(axis=1).all():land=times[k];break
   complete=bool(len(ci)==170 and np.array_equal(frame[ci],np.arange(170)) and ss[ci[-1]]['termination_terms']['motion_finished'] and not any(val for key,val in ss[ci[-1]]['termination_terms'].items() if key!='motion_finished'))
   jm=ci[(ts[ci]>=1.1)&(ts[ci]<=1.7)];lm=ci[(ts[ci]>=1.45)&(ts[ci]<=1.9)];sm=ci[(ct[ci]>=1.1)&(ct[ci]<=1.5)]
   phase[pi[times>=1.1]]='push_off'
   if air is not None:phase[pi[times>=air]]='flight'
   if land is not None:phase[pi[times>=land]]='post_landing'
   push=pi[(times>1.1)&(times<=air)] if air is not None else np.array([],dtype=int)
   mass=sum(runtime['masses_kg']);impulse=float(np.sum(np.concatenate([fz[push],gz[push]],axis=1))*.005) if len(push) else None
   record={'version':version,'case':case,'episode':int(e),'complete_success':complete,'samples':len(ci),'air_start_s':float(air) if air is not None else None,'landing_s':float(land) if land is not None else None,'air_duration_ms':float((land-air)*1000) if land is not None else None,'peak_base_z_m':float(z[jm].max()),'base_com_vz_peak_m_s':float(vz[jm].max()),'landing_min_base_z_m':float(z[lm].min()),'landing_height_rmse_m':rms(z[lm]-zr[lm]),'roll_peak_deg':float(np.abs(angles[ci,0]).max()),'axle_midpoint_dx_1p10_to_1p30_m':float(np.interp(1.3,times,wx[pi])-np.interp(1.1,times,wx[pi])),'axle_midpoint_dx_1p10_to_air_m':float(np.interp(air,times,wx[pi])-np.interp(1.1,times,wx[pi])) if air is not None else None,'support_impulse_1p10_to_air_Ns':impulse,'net_vertical_impulse_Ns':impulse-mass*9.81*(air-1.1) if impulse is not None else None,'left_shank_min_q_1p10_to_1p50_rad':float(q[sm,shankj[0]].min()),'right_shank_min_signed_q_1p10_to_1p50_rad':float((-q[sm,shankj[1]]).min()),'left_shank_extension_range_rad':float(np.ptp(q[sm,shankj[0]])),'max_abs_height_error_m':float(np.abs(z[ci]-zr[ci]).max())}
   episodes.append(record);cycles.append(record)
  joint=[]
  for j,n in enumerate(names):
   im=int(np.abs(v[:,j]).argmax());ia=int(np.abs(ac[:,j]).argmax());it=int(np.abs(tau[:,j]).argmax());limit=33 if 'wheel' in n else 10 if 'foot' in n else 20;eff=t['joint_effort_limits'][j]
   rec={'version':version,'case':case,'joint':n,'speed_peak_rad_s':float(np.abs(v[:,j]).max()),'speed_rms_rad_s':rms(v[:,j]),'peak_signed_speed_rad_s':float(v[im,j]),'speed_peak_time_s':float(pt[im]),'speed_peak_episode':int(pe[im]),'speed_peak_phase':str(phase[im]),'acceleration_peak_rad_s2':float(np.abs(ac[:,j]).max()),'acceleration_rms_rad_s2':rms(ac[:,j]),'acceleration_peak_time_s':float(pt[ia]),'acceleration_peak_phase':str(phase[ia]),'torque_peak_Nm':float(np.abs(tau[:,j]).max()),'computed_torque_peak_Nm':float(np.abs(computed[:,j]).max()),'torque_peak_time_s':float(pt[it]),'speed_limit_rad_s':limit,'overspeed_ms':int((np.abs(v[:,j])>limit+1e-5).sum())*5,'effort_limit_Nm':float(eff),'saturation_ms':int((np.abs(tau[:,j])>=eff*(1-1e-6)).sum())*5}
   for ph in ['preparation','push_off','flight','post_landing']:
    mask=phase==ph
    rec[ph+'_speed_peak_rad_s']=float(np.abs(v[mask,j]).max()) if mask.any() else None
   joint.append(rec);rows.append(rec)
  landmask=(ts>=1.45)&(ts<=1.9);jump=(ts>=1.1)&(ts<=1.7)
  stat={'metrics':res['metrics'],'telemetry_complete':True,'samples':len(ss),'physics_samples':len(ps),'joint_loads':joint,'episodes':episodes,'roll_peak_deg_all':float(np.abs(angles[:,0]).max()),'landing_height_rmse_m_all':rms(z[landmask]-zr[landmask]),'foot_vertical_force_peak_N':float(fz[:,:2].max()),'wheel_vertical_force_peak_N':float(fz[:,2:].max()),'ground_contact_peak_N':float(np.abs(gz).max()),'wheel_combined_speed_rms_rad_s':rms(v[:,wheelj]),'wheel_combined_acceleration_rms_rad_s2':rms(ac[:,wheelj]),'left_shank_reference_min_q_1p1_to_1p5_rad':float(qr[(ts>=1.1)&(ts<=1.5),shankj[0]].min())}
  for scope,ev in [('all',episodes),('complete',[x for x in episodes if x['complete_success']])]:
   stat[scope]={k:env([x[k] for x in ev]) for k in episodes[0] if k not in ('version','case','episode','complete_success','samples')}
  stats[version][case]=stat
  data[version,case]={'ct':ct,'pt':pt,'ts':ts,'ep':ep,'pe':pe,'z':z,'zr':zr,'q':q[:,shankj[0]],'qr':qr[:,shankj[0]],'roll':angles[:,0],'wheel':np.abs(v[:,wheelj]).max(axis=1)}
  motion_path=Path(md['motion_file']['path']);assert ref(motion_path)['sha256']==md['motion_file']['sha256']
runtime_comparison={}
for case in ['nominal','randomized']:
 runtime_comparison[case]={}
 for version in ['no_height','height']:
  runtime_comparison[case][version]={}
  for k in ['masses_kg','coms','material_properties','joint_stiffness','joint_damping']:
   a=np.array(rt[version,case][k]);b=np.array(rt['current',case][k])
   runtime_comparison[case][version][k]={'equal':bool(np.array_equal(a,b)),'max_abs_diff':float(np.abs(a-b).max())}
fig,axs=plt.subplots(4,2,figsize=(13,13),sharex=True)
for col,case in enumerate(['nominal','randomized']):
 for version,color in [('no_height','tab:orange'),('height','tab:green'),('current','tab:blue')]:
  c=data[version,case]
  for e in sorted(set(c['ep'])):
   mask=(c['ep']==e)&(c['ct']>=.85)&(c['ct']<=2.1);pm=(c['pe']==e)&(c['pt']>=.85)&(c['pt']<=2.1)
   for row,key in [(0,'z'),(2,'q'),(3,'roll')]:axs[row,col].plot(c['ct'][mask],c[key][mask],color=color,alpha=.75 if case=='nominal' else .35,label=version if e==0 else None)
   axs[1,col].plot(c['pt'][pm],c['wheel'][pm],color=color,alpha=.75 if case=='nominal' else .35,label=version if e==0 else None)
 c=data['current',case];m=(c['ep']==0)&(c['ts']>=.85)&(c['ts']<=2.1)
 axs[0,col].plot(c['ts'][m],c['zr'][m],'k--',label='reference');axs[2,col].plot(c['ts'][m],c['qr'][m],'k--',label='reference')
 for row,label in enumerate(['Base link height (m)','Max left/right wheel speed (rad/s)','Left shank position (rad)','Base roll (deg)']):
  axs[row,col].set_ylabel(label);axs[row,col].grid(alpha=.25)
  for x in [1.3,1.6]:axs[row,col].axvline(x,color='gray',ls=':',alpha=.4)
 axs[0,col].set_title(case);axs[0,col].legend(fontsize=8);axs[3,col].set_xlabel('Physical motion time (s); dotted lines = reference takeoff/landing')
fig.tight_layout();fig.savefig(out/'phase-comparison.png',dpi=150);plt.close(fig)
for name,records in [('joint-loads.csv',rows),('cycle-metrics.csv',cycles)]:
 with (out/name).open('x',newline='') as f:w=csv.DictWriter(f,fieldnames=list(records[0]));w.writeheader();w.writerows(records)
result={'version':1,'source':CODE_SOURCE,'inputs':inputs,'motion_reference':ref(motion_path),'statistics':stats,'runtime_comparison':runtime_comparison,'conventions':{'peaks':'All 1000 control steps and 4000 physical 5ms samples, including observed portion of truncated sixth cycle. Torques are applied actuator drive torque, not impact load. Acceleration from telemetry 5ms derivative.','cycle_averages':'complete scope uses only 170-frame motion_finished cycles with no other termination; all scope separately includes truncated cycle.','time':'physics frame/50+(substep+1)*.005; control frame/50+.02. Height RMSE uses commanded reference frame, consistent with old reports; plot reference uses original physical reference times.','contact':'First 15ms all eight monitored vertical contact forces below10N during1.15..1.6; landing first15ms either foot >=10N. Not proof of absence of every possible body contact.','impulse':'Sum eight ground-normal vertical forces*5ms for physical endpoint samples (1.10,air]; net subtracts actual total body mass*g*(air-1.1). This is not a slip energy loss estimate.','position':'Axle midpoint world x displacement; shank sign positive flexion for left, negative raw right. Min position over1.1..1.5s diagnoses extension.','runtime':'Matching startup masses/COM/material/PhysX gains does not prove identical software PD delay/gain draws.','scope':'One environment seed42, five complete cycles per case if successful. Nominal repetitions are deterministic, not independent trials; no convergence or hardware acceptance claim.'}}
with (out/'analysis.json').open('x') as f:json.dump(result,f,indent=2,allow_nan=False)
for version,sc in stats.items():
 for case,s in sc.items():
  print(version,case,json.dumps({'completed':s['metrics']['successful_motion_episodes'],'failed':s['metrics']['failed_episodes'],'wheel_peak':max(j['speed_peak_rad_s'] for j in s['joint_loads'] if 'wheel' in j['joint']),'wheel_acc_peak':max(j['acceleration_peak_rad_s2'] for j in s['joint_loads'] if 'wheel' in j['joint']),'shank_peak':max(j['speed_peak_rad_s'] for j in s['joint_loads'] if 'shank' in j['joint']),'wheel_rms':s['wheel_combined_speed_rms_rad_s'],'wheel_acc_rms':s['wheel_combined_acceleration_rms_rad_s2'],'roll':s['roll_peak_deg_all'],'landing_rmse':s['landing_height_rmse_m_all'],'complete':s['complete']}))
